    public DateTime LastInspected { get; set; }
}

using InventoryApp.Models;

namespace InventoryApp.Services;

public class EquipmentService
{
    public async Task<List<Equipment>> GetEquipmentAsync()
    {
        // Simulate network/database latency
        await Task.Delay(500);

        return new List<Equipment>
        {
            new() { Id = 1, Name = "Forklift A", Location = "Warehouse 1", LastInspected = new DateTime(2026, 3, 15) },
            new() { Id = 2, Name = "Conveyor Belt B", Location = "Warehouse 2", LastInspected = new DateTime(2026, 5, 22) },
            new() { Id = 3, Name = "Pallet Jack C", Location = "Dock 3", LastInspected = new DateTime(2026, 1, 10) },
            new() { Id = 4, Name = "Crane D", Location = "Yard", LastInspected = new DateTime(2025, 12, 5) },
            new() { Id = 5, Name = "Drill Press E", Location = "Workshop", LastInspected = new DateTime(2026, 6, 1) },
            new() { Id = 6, Name = "Lathe F", Location = "Workshop", LastInspected = new DateTime(2026, 4, 18) },
            new() { Id = 7, Name = "Compressor G", Location = "Utility Room", LastInspected = new DateTime(2026, 2, 28) },
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@using InventoryApp.Models
@using InventoryApp.Services
@inject EquipmentService EquipmentService
@inject PersistentComponentState PersistentState
@implements IDisposable

<h1>Equipment Inventory</h1>

@if (_equipment is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _equipment)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Equipment>? _equipment;
    private PersistingComponentStateSubscription _persistingSubscription;

    protected override async Task OnInitializedAsync()
    {
        _persistingSubscription = PersistentState.RegisterOnPersisting(PersistData);

        // Try to restore data persisted during prerender; only call service if not found.
        if (!PersistentState.TryTakeFromJson<List<Equipment>>("equipment", out var restored))
        {
            _equipment = await EquipmentService.GetEquipmentAsync();
        }
        else
        {
            _equipment = restored;
        }
    }

    private Task PersistData()
    {
        PersistentState.PersistAsJson("equipment", _equipment);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _persistingSubscription.Dispose();
    }
}

